    if (match) return {metal:match[1], units:1}
    match = /^[a-z_]+:raw_([a-z_]+)_block$/.exec(ref) || /^[a-z_]+:block_raw_([a-z_]+)$/.exec(ref)
    if (match) return {metal:match[1], units:9}
